const fs = require('fs');

function deepMerge(a, b) {
  if (!b) return a;
  const out = { ...a };
  for (const k of Object.keys(b)) {
    if (
      b[k] &&
      typeof b[k] === 'object' &&
      !Array.isArray(b[k]) &&
      a[k] &&
      typeof a[k] === 'object' &&
      !Array.isArray(a[k])
    ) {
      out[k] = deepMerge(a[k], b[k]);
    } else {
      out[k] = b[k];
    }
  }
  return out;
}

function loadGlobalVars() {
  const envJson = String($env.CASTUO_GLOBAL_VARS_JSON || '').trim();
  let base;
  if (envJson) base = JSON.parse(envJson);
  else {
    const p = String($env.CASTUO_GLOBAL_VARS_PATH || '').trim();
    if (!p) throw new Error('CASTUO_GLOBAL_VARS_JSON o CASTUO_GLOBAL_VARS_PATH requerido');
    base = JSON.parse(fs.readFileSync(p, 'utf8'));
  }
  const ov = String($env.CASTUO_GLOBAL_VARS_OVERRIDE_PATH || '').trim();
  if (ov && fs.existsSync(ov)) base = deepMerge(base, JSON.parse(fs.readFileSync(ov, 'utf8')));
  return base;
}

const cfg = loadGlobalVars();
const table = cfg.database.lecturas_sensores;
const lecturas = [];
let powerbi = { skipped: true, reason: 'streaming_endpoint vacío en global_vars' };
const url = cfg.external_services?.power_bi?.streaming_endpoint && String(cfg.external_services.power_bi.streaming_endpoint).trim();
if (url) {
  try {
    const r = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ rows: lecturas, source: 'castuo-n8n', ts: new Date().toISOString() }),
    });
    powerbi = { http_status: r.status, text: await r.text() };
  } catch (e) {
    powerbi = { error: e.message };
  }
}
const audit = {
  timestamp: new Date().toISOString(),
  operacion: 'Consultar Sensores → Power BI',
  tabla_consulta: table,
  filas: lecturas.length,
  workflow: 'CASTUO_Consultar_Sensores_PowerBI',
};
return [{ json: { castuo: cfg, lecturas, powerbi, audit, data_table_select: table } }];
